/**
 * Unit tests for NumberUtils.createNumber to maximize branch and line coverage.
 * Target: org.apache.commons.lang.math.NumberUtils
 */
public class NumberUtils_createNumber_TriageGen2Test {















    @Test
    public void testCreateNumber_DecimalAndExponent() {
        // Tests decPos > -1 and expPos > -1
        Number res = NumberUtils.createNumber("1.23e2");
        // 1.23e2 = 123.0. Since it has a dot, it goes to float/double/BigDecimal path
        assertTrue(res instanceof Double || res instanceof Float || res instanceof BigDecimal);
        assertEquals(123.0, ((Number)res).doubleValue(), 0.001);
    }






















}

